INSERT INTO `danh_muc` VALUES (1,'Laptop Gaming','Dành cho game thủ chuyên nghiệp với hiệu năng đồ họa cực đỉnh và tản nhiệt tối tân.'),(2,'Laptop Văn Phòng','Mỏng nhẹ, thời lượng pin dài, phù hợp cho học tập, công việc văn phòng và di chuyển nhiều.'),(3,'Laptop Đồ Họa','Cấu hình siêu mạnh mẽ, màn hình chuẩn màu chuyên thiết kế đồ họa 2D/3D và dựng phim chuyên nghiệp.'),(4,'Laptop Mỏng Nhẹ','Thiết kế siêu mỏng, trọng lượng nhẹ dưới 1.5kg, thời lượng pin dài phù hợp di chuyển nhiều.'),(5,'Laptop Sinh Viên','Giá thành hợp lý, cấu hình ổn định đáp ứng tốt nhu cầu học tập, làm văn phòng và giải trí cơ bản.'),(6,'Laptop AI','Tích hợp bộ xử lý NPU chuyên dụng, hỗ trợ các tính năng trí tuệ nhân tạo và tối ưu hiệu suất thông minh.');
/*!40000 ALTER TABLE `danh_muc` ENABLE KEYS */;
UNLOCK TABLES;

