INSERT INTO `phu_kien` VALUES (1,'Chuột Gaming Có Dây Razer DeathAdder V2',1290000.00,12,'https://product.hstatic.net/200000722513/product/chuot-gaming-da-v2-gearvn-1_59b42345fdb54b509619c7f74cdfb275_c0847dbc458942b1aba533c648341aa7_master.jpg',NULL,'Chuột','Razer','24 tháng','Dây cắm USB','RGB Razer Chroma','20000 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-08 04:57:09'),(2,'Chuột Máy Tính Không Dây Logitech MX Master 3S',2490000.00,12,'https://cdn2.cellphones.com.vn/insecure/rs:fill:0:358/q:90/plain/https://cellphones.com.vn/media/catalog/product/1/_/1_346.jpg',NULL,'Chuột','Logitech','12 ','Bluetooth / Receiver Logi Bolt','Không LED','8000 DPI','Khoảng cách kết nối 10m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-08 05:04:29'),(3,'Bàn phím cơ chuyên game ASUS ROG Strix Flare II',3490000.00,23,'https://cdn2.cellphones.com.vn/insecure/rs:fill:0:358/q:90/plain/https://cellphones.com.vn/media/catalog/product/g/r/group_185_1__1.png','Trang bị Foam tiêu âm tích hợp, tần số phản hồi 8000Hz siêu tốc và cụm phím điều khiển đa phương tiện bằng kim loại trực quan chuyên dụng cho game thủ.','Bàn phím','ASUS','24 tháng','Dây USB tháo rời','RGB từng phím Aura Sync',NULL,NULL,'Full-size',104,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-08 05:22:39'),(4,'Bàn phím cơ không dây Logitech G Pro X TKL Lightspeed',4390000.00,23,'https://cdn2.cellphones.com.vn/insecure/rs:fill:0:358/q:90/plain/https://cellphones.com.vn/media/catalog/product/b/a/ban-phim-gaming-logitech-pro-x-tkl-lightspeed-6.jpg','Dòng bàn phím cơ gaming không dây đỉnh cao được thiết kế đồng hành cùng các vận động viên Esports chuyên nghiệp, trang bị Switch GX chất lượng và túi bảo vệ đi kèm.','Bàn phím','Logitech','12 tháng','Không dây Lightspeed / Bluetooth / Dây Type-C','LIGHTSYNC RGB 16.8 triệu màu',NULL,NULL,'Tenkeyless (TKL)',87,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-08 05:25:45'),(5,'Tai nghe Gaming chụp tai Kingston HyperX Cloud III',1990000.00,23,'https://cdn2.cellphones.com.vn/insecure/rs:fill:0:358/q:90/plain/https://cellphones.com.vn/media/catalog/product/t/a/tai-nghe-gaming-co-day-hyperx-cloud-3_1_.png','Dòng tai nghe gaming huyền thoại tái xuất với lớp đệm da memory foam siêu êm ái, khung nhôm kim loại bền bỉ và màng loa 53mm được tinh chỉnh góc nghiêng tối ưu cho game thủ nghe rõ tiếng bước chân.','Tai nghe','HyperX','24 tháng','Jack 3.5mm / USB Type-C / USB Type-A',NULL,NULL,NULL,NULL,NULL,'Dài 15.5 cm - Rộng 8.5 cm - Cao 19.0 cm','308g','Âm thanh vòm DTS Headphone:X Spatial Audio','Có (Micro 10mm khử nhiễu độc quyền, có thể tháo rời)',NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-08 05:28:59'),(6,'Tai nghe không dây chống ồn Sony WH-1000XM5',6490000.00,21,'https://cdn2.cellphones.com.vn/insecure/rs:fill:0:358/q:90/plain/https://cellphones.com.vn/media/catalog/product/t/a/tai-nghe-chup-tai-sony-wh-1000xm5-3.png',NULL,'Tai nghe','Sony','12 tháng','Bluetooth 5.2 / Jack 3.5mm cắm dây',NULL,NULL,NULL,NULL,NULL,'Dài 16.5 cm - Rộng 7.5 cm - Cao 20.0 cm','250g','Hi-Res Audio / Cơ chế tăng cường âm thanh kỹ thuật số DSEE Extreme','Có (4 micro định hướng chùm sóng tích hợp AI chống ồn cuộc gọi)','30 giờ (Bật chống ồn) / 40 giờ (Tắt chống ồn)',NULL,NULL,NULL,NULL,NULL,'2026-06-08 05:42:12'),(8,'Củ sạc nhanh Asus ROG 100W Type-C AC100-02',950000.00,15,'https://dlcdnwebimgs.asus.com/gain/3C53BB35-AE89-4715-B752-B27AF990409C/w1000/h732',NULL,'Sạc laptop','Asus','12 tháng','Type-C',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'100W','100-240V ~ 50/60Hz 1.6A','20.0V - 5.0A (100W), 15.0V - 3.0A, 9.0V - 3.0A, 5.0V - 3.0A',NULL,'2026-06-08 06:25:20'),(9,'Cục sạc Laptop Acer Gaming 180W',1450000.00,23,'https://cdni.dienthoaivui.com.vn/x420,webp,q100/https://media-asset.dienthoaivui.com.vn/uploads/wp-content/uploads/images/sac-laptop-acer-19-5v-9-23a-180w-dau-thuong-4.jpg','Sạc zin chính hãng dành cho các dòng laptop Acer Nitro 5, Acer Aspire 7 và Predator Helios. Trang bị mạch bảo vệ thông minh chống quá tải, đoản mạch, giúp cung cấp dòng điện ổn định tuyệt đối khi laptop bung tối đa hiệu năng CPU và GPU để chiến game AAA hoặc stress test phần cứng.','Sạc laptop','Acer','12 tháng','Đầu tròn (Chân kim 5.5mm x 1.7mm)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'180W','100-240V ~ 50/60Hz 2.34A','19.5V - 9.23A (180W)',NULL,'2026-06-08 06:28:27'),(10,'Chuột Bluetooth Silent Logitech Signature M650',650000.00,10,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/86/299931/chuot-khong-day-logitech-silent-signature-m650-size-m-den-3-638620837125359414-750x500.jpg','Chuột Bluetooth Logitech Signature M650 mang đến trải nghiệm làm việc yên tĩnh và hiệu quả với công nghệ SilentTouch giảm 90% tiếng ồn khi nhấp chuột. Sản phẩm nổi bật với con lăn SmartWheel thông minh, tự động điều chỉnh độ chính xác và tốc độ cuộn. Thiết kế công thái học vừa vặn, hỗ trợ kết nối không dây linh hoạt qua Bluetooth hoặc đầu thu USB Logi Bolt. Thời lượng pin ấn tượng lên đến 24 tháng, giúp bạn làm việc không gián đoạn.','Chuột',' Logitech','12 tháng','Không dây Bluetooth',NULL,'4000 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:01:13'),(13,'Chuột Bluetooth Akko Cat Theme Mouse Pink ANGIE',270000.00,12,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/86/342568/chuot-bluetooth-akko-cat-theme-mouse-pink-angie-1-638913000869081581-750x500.jpg','Chuột Bluetooth Akko Cat Theme Mouse Pink ANGIE sở hữu thiết kế độc đáo với chủ đề chú mèo dễ thương cùng tông màu hồng pastel ngọt ngào, phù hợp cho người dùng yêu thích sự cá tính. Chuột được trang bị kết nối không dây ổn định, mang lại sự linh hoạt tối đa cho không gian làm việc. Với thiết kế nhỏ gọn, công thái học, sản phẩm giúp giảm mỏi tay khi sử dụng trong thời gian dài. Đây là lựa chọn hoàn hảo để kết hợp cùng bàn phím và bộ phụ kiện cùng chủ đề, tạo nên góc làm việc sáng tạo và nổi bật.','Chuột','Akko','12 tháng','Không dây Bluetooth',NULL,' 1200 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:03:24'),(14,'Chuột sạc Bluetooth Gaming Razer Basilisk V3 Pro 35K',3700000.00,7,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/86/357676/chuot-sac-bluetooth-gaming-razer-basilisk-v3-pro-35k-1-638990595809456056-750x500.jpg',NULL,'Chuột','Razer','12 tháng ','Không dây Gaming Bluetooth',NULL,'35000 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:05:34'),(15,'Chuột Có dây Gaming Rapoo V10SE',60000.00,30,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/86/339137/chuot-co-day-gaming-rapoo-v10s-den-1-638849072019516231-750x500.jpg','Chuột Gaming Rapoo V10SE sở hữu thiết kế công thái học hiện đại, mang lại cảm giác cầm nắm chắc chắn và thoải mái cho game thủ trong những trận chiến kéo dài. Sản phẩm được trang bị cảm biến quang học với DPI có thể tùy chỉnh linh hoạt, đảm bảo độ chính xác cao trong mọi thao tác di chuyển. Hệ thống đèn LED RGB rực rỡ và các nút bấm bền bỉ giúp nâng cao trải nghiệm thẩm mỹ cũng như hiệu suất chơi game. Đây là lựa chọn lý tưởng cho các game thủ đang tìm kiếm sự bền bỉ, ổn định và phong cách ấn tượng trong tầm giá phổ thông.','Chuột',' Rapoo','12 tháng','Có dây Gaming',NULL,'1600 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:08:06'),(16,'Chuột Không dây Silent Rapoo B2S',159000.00,32,'https://cdn.tgdd.vn/Products/Images/86/314637/chuot-khong-day-silent-rapoo-b2s-1-750x500.jpg','Chuột không dây Silent Rapoo B2S là sự kết hợp hoàn hảo giữa thiết kế tinh tế và hiệu năng yên tĩnh. Sản phẩm sử dụng công nghệ phím bấm Silent, giúp giảm thiểu tối đa tiếng ồn khi nhấp chuột, tạo không gian làm việc tập trung và chuyên nghiệp. Với kết nối không dây 2.4GHz ổn định, chuột mang lại độ nhạy cao và khả năng phản hồi mượt mà. Kiểu dáng gọn nhẹ, công thái học giúp người dùng thoải mái sử dụng trong thời gian dài mà không gây mỏi tay, rất phù hợp cho dân văn phòng và sinh viên.','Chuột',' Rapoo','12 tháng','Không dây',NULL,' 1200 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:10:54'),(17,'Chuột sạc Bluetooth HyperWork Silentium Gen 2',570000.00,12,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/86/362508/chuot-sac-bluetooth-hyperwork-silentium-gen-2-trang-1-639058120739729652-750x500.jpg','Chuột Bluetooth HyperWork Silentium Gen 2 là sự lựa chọn tối ưu cho người dùng hiện đại với thiết kế mỏng nhẹ, tinh tế và khả năng vận hành cực kỳ yên tĩnh nhờ các nút bấm Silent. Sản phẩm được trang bị kết nối đa thiết bị linh hoạt qua cả Bluetooth và Wireless 2.4GHz, giúp chuyển đổi mượt mà giữa các máy tính khác nhau. Với pin sạc tích hợp thông minh, bạn không còn lo lắng về việc thay pin định kỳ. Bề mặt chuột được phủ lớp hoàn thiện cao cấp, mang lại cảm giác cầm nắm dễ chịu và bền bỉ trong suốt quá trình sử dụng.','Chuột',' HyperWork.','12 tháng',' Không dây Bluetooth',NULL,'1000/1600/2400/3200/4800 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:14:38'),(18,'Chuột sạc Bluetooth Silent Logitech MX Master 3s',2235000.00,7,'https://cdn.tgdd.vn/Products/Images/86/326659/chuot-bluetooth-silent-logitech-mx-master-3s-den-1-750x500.jpg','Chuột Bluetooth Logitech MX Master 3S là biểu tượng của sự chuyên nghiệp, được nâng cấp với cảm biến 8.000 DPI cho độ chính xác trên mọi bề mặt, kể cả mặt kính. Công nghệ Quiet Click giúp mọi cú nhấp chuột trở nên yên tĩnh tuyệt đối nhưng vẫn đảm bảo độ phản hồi xúc giác ấn tượng. Con lăn MagSpeed điện từ cho phép cuộn tới 1.000 dòng mỗi giây một cách im lặng và chính xác đến từng pixel. Với thiết kế công thái học hoàn hảo và khả năng kết nối đa thiết bị, đây là công cụ làm việc không thể thiếu cho các nhà thiết kế, lập trình viên và người dùng văn phòng cao cấp.','Chuột','Logitech','12 tháng',' Không dây Bluetooth',NULL,'8000 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:17:02'),(19,'Chuột Không dây Zadez M325 Tuxedo',195000.00,12,'https://cdn.tgdd.vn/Products/Images/86/151027/chuot-khong-day-zadez-m325-den-1-750x500.jpg','Chuột không dây Zadez M325 Tuxedo sở hữu thiết kế lấy cảm hứng từ phong cách Tuxedo lịch lãm với sự kết hợp hài hòa giữa các đường nét tinh tế và độ hoàn thiện cao. Sản phẩm mang lại sự tiện lợi tối đa với kết nối không dây 2.4GHz ổn định, đảm bảo mọi thao tác di chuyển đều mượt mà và chính xác. Với kích thước nhỏ gọn, vừa vặn trong lòng bàn tay cùng độ nhạy DPI linh hoạt, đây là phụ kiện lý tưởng giúp tối ưu hóa công việc hàng ngày của bạn. Zadez M325 Tuxedo không chỉ là một công cụ hỗ trợ mà còn là điểm nhấn sang trọng cho không gian làm việc của bạn.','Chuột',' Zadez','12 tháng','Đầu thu USB Receiver',NULL,'1600 DPI',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 09:19:14'),(20,'Bàn Phím Cơ Có Dây Gaming Razer BlackWidow V4 75% White Edition',3640000.00,6,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/4547/357640/ban-phim-co-co-day-gaming-razer-blackwidow-v4-75-white-edition-trang-1-638959705314862025-750x500.jpg','Bàn phím cơ Gaming Razer BlackWidow V4 75% White Edition mang đến sự kết hợp hoàn hảo giữa hiệu năng đỉnh cao và thiết kế nhỏ gọn, sang trọng với tông màu trắng tinh tế. Sở hữu layout 75% tiết kiệm không gian, bàn phím được trang bị switch cơ học Razer cho cảm giác gõ phím mượt mà, phản hồi cực nhanh và độ bền vượt trội. Công nghệ Razer Chroma RGB cho phép tùy chỉnh ánh sáng trên từng phím, tạo nên không gian chơi game rực rỡ và cá tính. Với khung nhôm chắc chắn cùng các phím điều khiển đa phương tiện chuyên dụng, đây là lựa chọn lý tưởng cho các game thủ đòi hỏi cả thẩm mỹ lẫn hiệu suất làm việc chuyên nghiệp.','Bàn phím','Razer','12 tháng','Kết nối có dây qua cổng Type-C','Razer Chroma RGB',NULL,NULL,' Cỡ 75%',81,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 10:26:06'),(21,'Bàn Phím Cơ Bluetooth Machenike KG98 RGB Purple-Gold Switch',1490000.00,12,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/4547/361813/ban-phim-co-bluetooth-machenike-kg98-rgb-purple-gold-switch-den-1-639053085879866643-750x500.jpg','Bàn phím cơ Machenike KG98 RGB Purple-Gold Switch sở hữu thiết kế độc đáo với phối màu sang trọng, thu hút mọi ánh nhìn ngay từ lần đầu tiên. Bàn phím được trang bị kết nối Bluetooth linh hoạt, cho phép bạn dễ dàng kết nối với nhiều thiết bị mà không cần dây nối rườm rà. Hệ thống switch Purple-Gold mang lại cảm giác gõ phím êm ái, phản hồi xúc giác ấn tượng và độ bền cao, phù hợp cho cả nhu cầu chơi game lẫn làm việc văn phòng. Bên cạnh đó, hệ thống đèn nền RGB rực rỡ có thể tùy chỉnh màu sắc giúp tạo nên không gian làm việc đầy cá tính và chuyên nghiệp.','Bàn phím','Trung Quốc','12 tháng ','USB Receiver (đầu thu USB) Kết nối có dây qua cổng Type-C Bluetooth 5.0','RGB',NULL,NULL,' Full size',98,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 10:27:53'),(22,'Bàn Phím Bluetooth Logitech K380s',730000.00,12,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/4547/323008/ban-phim-bluetooth-logitech-k380s-den-3-638620800915830579-750x500.jpg',NULL,'Bàn phím','Logitech','12 tháng ',' Bluetooth','Không ',NULL,NULL,'Compact (Rút gọn)',79,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-02 10:30:37'),(23,'Bàn Phím Cơ Bluetooth Akko TAC87 Matcha Red Bean Stellar Rose',1180000.00,11,'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/4547/351689/ban-phim-co-bluetooth-akko-ac87-matcha-red-bean-stellar-rose-1-638941343084066302-750x500.jpg','Bàn phím cơ Bluetooth Akko TAC87 Matcha Red Bean Stellar Rose là sự kết hợp hoàn hảo giữa phong cách thiết kế lấy cảm hứng từ trà Matcha đậu đỏ và tông màu Stellar Rose độc đáo, tạo nên vẻ ngoài ấn tượng và đầy cá tính. Bàn phím sở hữu layout TKL (87 phím) nhỏ gọn, giúp tối ưu diện tích bàn làm việc mà vẫn đảm bảo đầy đủ các chức năng cần thiết. Với khả năng kết nối Bluetooth linh hoạt, người dùng có thể dễ dàng sử dụng bàn phím trên nhiều thiết bị khác nhau mà không bị hạn chế bởi dây cáp. Bên cạnh đó, chất lượng swit