  `pin` varchar(500) DEFAULT NULL,
  `he_dieu_hanh` varchar(255) DEFAULT NULL,
  `gia` decimal(15,2) NOT NULL,
  `so_luong_ton` int DEFAULT '0',
  `anh_dai_dien` varchar(255) DEFAULT NULL,
  `mo_ta` text,
  `ngay_tao` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ma_san_pham`),
  KEY `ma_thuong_hieu` (`ma_thuong_hieu`),
  KEY `ma_danh_muc` (`ma_danh_muc`),
  KEY `ma_khuyen_mai` (`ma_khuyen_mai`),
  CONSTRAINT `FK_san_pham_danh_muc` FOREIGN KEY (`ma_danh_muc`) REFERENCES `danh_muc` (`ma_danh_muc`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `FK_san_pham_khuyen_mai` FOREIGN KEY (`ma_khuyen_mai`) REFERENCES `khuyen_mai` (`ma_khuyen_mai`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_san_pham_thuong_hieu` FOREIGN KEY (`ma_thuong_hieu`) REFERENCES `thuong_hieu` (`ma_thuong_hieu`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `san_pham_ibfk_1` FOREIGN KEY (`ma_thuong_hieu`) REFERENCES `thuong_hieu` (`ma_thuong_hieu`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `san_pham_ibfk_2` FOREIGN KEY (`ma_danh_muc`) REFERENCES `danh_muc` (`ma_danh_muc`),
  CONSTRAINT `san_pham_ibfk_3` FOREIGN KEY (`ma_khuyen_mai`) REFERENCES `khuyen_mai` (`ma_khuyen_mai`)
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
